 "content": "from collections import deque


def transform(grid):
    """Reverse the nested color layers independently in each nonzero object."""
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] != 0 and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))

            colors = {grid[y][x] for y, x in cells}
            boxes = {}
            for color in colors:
                coords = [(y, x) for y, x in cells if grid[y][x] == color]
                min_y = min(y for y, _ in coords)
                max_y = max(y for y, _ in coords)
                min_x = min(x for _, x in coords)
                max_x = max(x for _, x in coords)
                boxes[color] = ((max_y - min_y + 1) * (max_x - min_x + 1), color)
            layers = sorted(colors, key=lambda color: (-boxes[color][0], color))
            remap = dict(zip(layers, reversed(layers)))
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]

    return out
